#include <iostream>
#include <string>
#include <string_view>

bool replaceString(std::string& s, std::string_view oldSubStr, std::string_view newSubStr) {
    if (oldSubStr.empty()) {
        return false;
    }
    bool isReplaced = false;
    std::string::size_type currentPosition = 0;

    while (currentPosition < s.length()) {
        std::string::size_type position = s.find(oldSubStr, currentPosition);
        if (position == std::string::npos) {
            break;
        }
        s.replace(position, oldSubStr.length(), newSubStr);
        currentPosition = position + newSubStr.length();
        isReplaced = true;
    }

    return isReplaced;
}

int main() {
    std::string s;
    std::string oldSub;
    std::string newSub;

    if (std::cin >> s >> oldSub >> newSub) {
        bool replaced = replaceString(s, oldSub, newSub);
        if (replaced) {
            std::cout << "The replaced string is " << s << "\n";
        } else {
            std::cout << "No matches\n";
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>

class Circle {
private:
    double radius;

public:
    Circle() : radius(1.0) {}
    Circle(double r) : radius(r) {}

    double getRadius() const {
        return radius;
    }

    void setRadius(double r) {
        radius = r;
    }

    double getArea() const {
        return 3.141592653589793 * radius * radius;
    }
};

// Pass by value: copies the object
void modifyByValue(Circle c) {
    c.setRadius(20.0);
}

// Pass by reference: modifies original object
void modifyByReference(Circle& c) {
    c.setRadius(10.0);
}

// Pass by const reference: read-only, efficient
void printCircle(const Circle& c) {
    std::cout << "Radius: " << std::fixed << std::setprecision(1) << c.getRadius()
              << ", Area: " << std::setprecision(4) << c.getArea() << "\n";
}

int main() {
    Circle myCircle(5.0);
    std::cout << "Initial state: ";
    printCircle(myCircle);

    modifyByValue(myCircle);
    std::cout << "After modifyByValue: ";
    printCircle(myCircle);

    modifyByReference(myCircle);
    std::cout << "After modifyByReference: ";
    printCircle(myCircle);

    return 0;
}
